// Package authz is RBAC + tenant data-scope (modules/authz): the role ×
// resource × action policy, the STREAMHUB_AUTHZ_ENFORCE phased switch and
// the PermissionGuard, here a huma middleware enforcing the permission an
// operation declares with Require (the @RequirePermission decorator).
//
// The Node core runs casbin with an RBAC-with-domains model, but it seeds no
// `g` grouping rules, so g(r.sub, p.sub, dom) reduces to role equality and the
// whole enforcer is the small matcher in Can (locked against a truth table
// generated by casbin itself, testdata/casbin_truth_table.json).
package authz

import (
	"context"
	"database/sql"
	"os"
	"strings"
	"sync"

	"github.com/streamhubstudio/streamhub/streamhub-core-go/internal/auth"
)

// EnforceEnv is the phased-enforcement switch.
const EnforceEnv = "STREAMHUB_AUTHZ_ENFORCE"

// EnforcementMode is off | log | on.
type EnforcementMode string

const (
	ModeOff EnforcementMode = "off"
	ModeLog EnforcementMode = "log"
	ModeOn  EnforcementMode = "on"
)

// Mode resolves STREAMHUB_AUTHZ_ENFORCE on every call: unset/invalid → on
// (secure by default); explicit off/log win.
func Mode() EnforcementMode {
	raw := strings.ToLower(strings.TrimSpace(os.Getenv(EnforceEnv)))
	if raw == "" {
		raw = "on"
	}
	switch EnforcementMode(raw) {
	case ModeOff, ModeLog, ModeOn:
		return EnforcementMode(raw)
	}
	return ModeOn
}

// Roles of the model (domain = tenant).
var Roles = []string{"superadmin", "owner", "editor", "viewer", "service"}

// Resources guarded by Require.
var Resources = []string{"app", "config", "s3", "stream", "recording", "vod", "broadcast", "sample", "ingress", "tenant", "usage", "token"}

// Actions a principal can take.
var Actions = []string{"read", "create", "write", "delete", "start", "stop"}

// Policy is one [sub, dom, obj, act] rule.
type Policy struct{ Sub, Dom, Obj, Act string }

// Policies is rbacPolicies(): superadmin is intentionally absent (it
// bypasses in the guard, so a bad policy can never lock it out).
func Policies() []Policy {
	rules := []Policy{
		{"owner", "*", "*", "*"},
		{"viewer", "*", "*", "read"},
	}
	editor := [][2]string{
		{"app", "create"}, {"app", "write"},
		{"config", "read"}, {"config", "write"},
		{"s3", "read"}, {"s3", "write"},
		{"stream", "read"}, {"stream", "write"}, {"stream", "start"}, {"stream", "stop"}, {"stream", "delete"},
		{"recording", "read"}, {"recording", "start"}, {"recording", "stop"}, {"recording", "write"},
		{"vod", "read"}, {"vod", "write"}, {"vod", "delete"},
		{"broadcast", "read"}, {"broadcast", "start"}, {"broadcast", "stop"}, {"broadcast", "write"},
		{"sample", "read"}, {"sample", "write"},
		{"ingress", "read"}, {"ingress", "create"}, {"ingress", "write"}, {"ingress", "delete"},
		{"usage", "read"},
	}
	for _, oa := range editor {
		rules = append(rules, Policy{"editor", "*", oa[0], oa[1]})
	}
	return append(rules, Policy{"service", "*", "*", "*"})
}

var policies = Policies()

// Can is the pure RBAC verdict: may role do action on resource in tenant?
func Can(role, tenant, resource, action string) bool {
	for _, p := range policies {
		if p.Sub == role && (p.Dom == "*" || p.Dom == tenant) &&
			(p.Obj == "*" || p.Obj == resource) && (p.Act == "*" || p.Act == action) {
			return true
		}
	}
	return false
}

// Service holds the DB-backed helpers (app id / tenant lookups).
type Service struct {
	db *sql.DB

	once         sync.Once
	hasTenantCol bool
}

// New builds the service over the global DB.
func New(global *sql.DB) *Service { return &Service{db: global} }

// CanPrincipal applies Can with the principal's role and tenant (default platform).
func (s *Service) CanPrincipal(p *auth.Principal, resource, action string) bool {
	dom := p.TenantID
	if dom == "" {
		dom = auth.PlatformTenantID
	}
	return Can(string(p.Role), dom, resource, action)
}

// AppIDByName resolves an app's numeric id; ok=false if unknown or on error.
func (s *Service) AppIDByName(ctx context.Context, app string) (int64, bool) {
	var id sql.NullInt64
	if err := s.db.QueryRowContext(ctx, `SELECT id FROM apps WHERE name = ?`, app).Scan(&id); err != nil || !id.Valid {
		return 0, false
	}
	return id.Int64, true
}

// AppBelongsToTenant is the data-scope check. Unknown app, unassigned app,
// unscoped/superadmin caller or pre-migration schema → true (no signal, no block).
func (s *Service) AppBelongsToTenant(ctx context.Context, p *auth.Principal, app string) bool {
	if p.IsSuperadmin || p.TenantID == "" {
		return true
	}
	s.once.Do(func() {
		rows, err := s.db.QueryContext(ctx, `PRAGMA table_info(apps)`)
		if err != nil {
			return
		}
		defer rows.Close()
		for rows.Next() {
			var (
				cid, notnull, pk int
				name, typ        string
				dflt             sql.NullString
			)
			if rows.Scan(&cid, &name, &typ, &notnull, &dflt, &pk) == nil && name == "tenant_id" {
				s.hasTenantCol = true
			}
		}
	})
	if !s.hasTenantCol {
		return true
	}
	var tenant sql.NullString
	if err := s.db.QueryRowContext(ctx, `SELECT tenant_id FROM apps WHERE name = ?`, app).Scan(&tenant); err != nil {
		return true
	}
	if !tenant.Valid {
		return true
	}
	return tenant.String == p.TenantID
}
